CREATE DATABASE IF NOT EXISTS bansos_transparan CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci; USE bansos_transparan;
CREATE TABLE branches(id INT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(30) UNIQUE NOT NULL,name VARCHAR(120) NOT NULL,region VARCHAR(150) NOT NULL,allocated_budget DECIMAL(15,2) NOT NULL DEFAULT 0,disbursed_total DECIMAL(15,2) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,username VARCHAR(80) UNIQUE NOT NULL,nik VARCHAR(30) UNIQUE NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('super_admin','branch_admin','citizen') NOT NULL,branch_id INT NULL,qr_token VARCHAR(100) UNIQUE NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE branch_budget_logs(id INT AUTO_INCREMENT PRIMARY KEY,branch_id INT NOT NULL,amount DECIMAL(15,2) NOT NULL,notes TEXT NULL,allocated_date DATE NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE aid_schedules(id INT AUTO_INCREMENT PRIMARY KEY,branch_id INT NOT NULL,title VARCHAR(150) NOT NULL,schedule_date DATE NOT NULL,start_time TIME NULL,end_time TIME NULL,history_table_name VARCHAR(100) NOT NULL,status ENUM('draft','active','completed') NOT NULL DEFAULT 'draft',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE issue_reports(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,branch_id INT NOT NULL,schedule_id INT NULL,subject VARCHAR(150) NOT NULL,description TEXT NOT NULL,status ENUM('open','in_progress','resolved') NOT NULL DEFAULT 'open',admin_response TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE CASCADE,FOREIGN KEY(schedule_id) REFERENCES aid_schedules(id) ON DELETE SET NULL) ENGINE=InnoDB;